from ase.io import read
import numpy as np

def rot_vec(v,axis,theta):
 axis=axis/np.linalg.norm(axis)
 return v*np.cos(theta)+np.cross(axis,v)*np.sin(theta)+axis*np.dot(axis,v)*(1-np.cos(theta))
base=read('assembled.xyz')
for tilt in np.linspace(-50,0,11):
 m=base.copy(); mid=(m.positions[35]+m.positions[36])/2; ax=np.array([0.,1.,0.])
 for i in range(30,46): m.positions[i]=mid+rot_vec(m.positions[i]-mid,ax,np.deg2rad(tilt))
 best=(0,None,None)
 for ang in np.linspace(0,360,121):
  mm=m.copy(); axis=mm.positions[10]-mm.positions[2]; origin=mm.positions[10]
  for i in [22,23,24]: mm.positions[i]=origin+rot_vec(mm.positions[i]-origin,axis,np.deg2rad(ang))
  p=mm.positions
  dm1=np.linalg.norm(p[1:30,None]-p[None,30:46],axis=2).min()
  dm2=np.linalg.norm(p[1:30,None]-p[None,46:92],axis=2).min()
  val=min(dm1,dm2)
  if val>best[0]: best=(val,ang,(dm1,dm2))
 print(f'{tilt:5.1f}',best)
